# -*- coding: utf-8 -*-
"""
金渐层小猫桌面宠物 - 单文件版
图片已嵌入，无需外部pet.png
"""

import sys
import os
import base64
import random
import tempfile
from PyQt5.QtWidgets import (QApplication, QWidget, QLabel, QMenu, QAction)
from PyQt5.QtGui import QPixmap, QTransform, QFont, QImage
from PyQt5.QtCore import Qt, QPoint, QTimer, QByteArray

# 内嵌图片数据
IMG_B64 = ""

# 对话池
DIALOGUES = {
    "jump": ["咻！起飞~", "我跳！", "蹦蹦跳跳", "看我轻功！"],
    "squash": ["唔！被压扁了", "弹弹弹~", "轻点啦！", "回弹！"],
    "shake": ["晕晕晕...", "别晃啦！", "脑袋要甩飞了", "天旋地转"],
    "touch_head": ["呼噜呼噜~", "好舒服，再摸摸", "最喜欢主人了", "继续不要停", "幸福ing"],
    "feed": ["吧唧吧唧", "小鱼干！", "好吃好吃", "还要还要", "满足~"],
    "drink": ["咕嘟咕嘟", "啊~解渴", "水水真好喝", "再喝一口"],
    "off_work": ["什么时候下班啊", "摸鱼中勿扰", "上班如上坟", "想回家躺平", "倒计时开始"],
    "run": ["冲鸭！", "我跑我跑", "追不上我~", "奔跑吧小猫！", "风一样的男子"]
}

ANIMATIONS = ["jump", "squash", "shake", "touch_head", "feed", "drink", "off_work", "run"]


class PetWindow(QWidget):
    def __init__(self):
        super().__init__()
        self.scale = 1.0
        self.min_scale = 0.3
        self.max_scale = 3.0
        self.drag_pos = QPoint()
        self.is_dragging = False
        self.is_animating = False
        self.anim_index = 0
        self.is_flipped = False
        self.is_running = False
        self.run_frame = 0

        # 窗口设置
        self.setWindowFlags(Qt.FramelessWindowHint | Qt.WindowStaysOnTopHint | Qt.Tool)
        self.setAttribute(Qt.WA_TranslucentBackground)

        # 从base64加载图片
        img_data = QByteArray.fromBase64(IMG_B64.encode())
        self.original_pixmap = QPixmap()
        self.original_pixmap.loadFromData(img_data, "PNG")

        if self.original_pixmap.isNull():
            print("错误：图片加载失败")
            sys.exit(1)

        # 小猫标签
        self.pet_label = QLabel(self)
        self.pet_label.setAlignment(Qt.AlignCenter)
        self.pet_label.setAttribute(Qt.WA_TranslucentBackground)

        # 对话气泡
        self.bubble = QLabel("", self)
        self.bubble.setStyleSheet(
            "background-color: white; color: #222; "
            "padding: 6px 10px; border-radius: 8px; "
            "border: 1px solid #ddd;"
        )
        self.bubble.setFont(QFont("微软雅黑", 10))
        self.bubble.setAlignment(Qt.AlignCenter)
        self.bubble.hide()
        self.bubble_timer = QTimer(self)
        self.bubble_timer.setSingleShot(True)
        self.bubble_timer.timeout.connect(self.bubble.hide)

        # 奔跑定时器
        self.run_timer = QTimer(self)
        self.run_timer.timeout.connect(self.run_step)
        self.run_direction = 1
        self.run_speed = 8

        # 动画定时器
        self.anim_timer = QTimer(self)
        self.anim_timer.timeout.connect(self.anim_step)
        self.anim_frame = 0
        self.anim_type = ""
        self.anim_base_x = 0
        self.anim_base_y = 0
        self.anim_base_w = 0
        self.anim_base_h = 0
        self.anim_total = 0

        self.update_pet_size()

        # 初始位置
        screen = QApplication.primaryScreen().geometry()
        self.move(screen.width() - self.width() - 80,
                  screen.height() - self.height() - 120)

    def update_pet_size(self):
        w = max(10, int(self.original_pixmap.width() * self.scale))
        h = max(10, int(self.original_pixmap.height() * self.scale))
        pix = self.original_pixmap.scaled(w, h, Qt.KeepAspectRatio, Qt.SmoothTransformation)
        if self.is_flipped:
            pix = pix.transformed(QTransform().scale(-1, 1), Qt.SmoothTransformation)
        self.pet_label.setPixmap(pix)
        self.pet_label.setFixedSize(w, h)
        self.setFixedSize(w, h)

    # 鼠标事件
    def mousePressEvent(self, event):
        if event.button() == Qt.LeftButton:
            self.drag_pos = event.globalPos() - self.frameGeometry().topLeft()
            self.is_dragging = False
            self.press_pos = event.globalPos()
        elif event.button() == Qt.RightButton:
            self.show_right_menu(event.globalPos())

    def mouseMoveEvent(self, event):
        if event.buttons() == Qt.LeftButton:
            if (event.globalPos() - self.press_pos).manhattanLength() > 5:
                self.is_dragging = True
            self.move(event.globalPos() - self.drag_pos)

    def mouseReleaseEvent(self, event):
        if event.button() == Qt.LeftButton and not self.is_dragging:
            if not self.is_animating and not self.is_running:
                self.trigger_interaction()
        self.is_dragging = False

    def wheelEvent(self, event):
        new_scale = self.scale + (0.1 if event.angleDelta().y() > 0 else -0.1)
        new_scale = max(self.min_scale, min(self.max_scale, new_scale))
        if new_scale != self.scale:
            cx = self.x() + self.width() // 2
            cy = self.y() + self.height() // 2
            self.scale = new_scale
            self.update_pet_size()
            self.move(cx - self.width() // 2, cy - self.height() // 2)

    # 右键菜单
    def show_right_menu(self, pos):
        menu = QMenu()
        menu.setStyleSheet("QMenu { padding: 5px; } QMenu::item { padding: 6px 20px; }")

        interact_menu = menu.addMenu("互动")
        for name, key in [("摸摸头","touch_head"),("喂饭","feed"),("喝水","drink"),
                          ("下班了吗","off_work"),("来回奔跑","run"),
                          ("跳跃","jump"),("压扁","squash"),("抖动","shake")]:
            act = QAction(name, self)
            act.triggered.connect(lambda checked, k=key: self.manual_interact(k))
            interact_menu.addAction(act)

        menu.addSeparator()
        for name, amt in [("放大",0.2),("缩小",-0.2)]:
            act = QAction(name, self)
            act.triggered.connect(lambda checked, a=amt: self.zoom(a))
            menu.addAction(act)
        act_reset = QAction("重置大小", self)
        act_reset.triggered.connect(self.reset_scale)
        menu.addAction(act_reset)

        menu.addSeparator()
        self.act_topmost = QAction("取消置顶", self)
        self.act_topmost.triggered.connect(self.toggle_topmost)
        menu.addAction(self.act_topmost)

        menu.addSeparator()
        act_exit = QAction("退出程序", self)
        act_exit.triggered.connect(QApplication.quit)
        menu.addAction(act_exit)

        menu.exec(pos)

    def zoom(self, amount):
        cx = self.x() + self.width() // 2
        cy = self.y() + self.height() // 2
        self.scale = max(self.min_scale, min(self.max_scale, self.scale + amount))
        self.update_pet_size()
        self.move(cx - self.width() // 2, cy - self.height() // 2)

    def reset_scale(self):
        cx = self.x() + self.width() // 2
        cy = self.y() + self.height() // 2
        self.scale = 1.0
        self.update_pet_size()
        self.move(cx - self.width() // 2, cy - self.height() // 2)

    def toggle_topmost(self):
        flags = self.windowFlags()
        if flags & Qt.WindowStaysOnTopHint:
            self.setWindowFlags(flags & ~Qt.WindowStaysOnTopHint)
            self.act_topmost.setText("始终置顶")
        else:
            self.setWindowFlags(flags | Qt.WindowStaysOnTopHint)
            self.act_topmost.setText("取消置顶")
        self.show()

    # 互动
    def manual_interact(self, anim_type):
        if self.is_animating or self.is_running:
            return
        self.play_animation(anim_type)

    def trigger_interaction(self):
        anim_type = ANIMATIONS[self.anim_index % len(ANIMATIONS)]
        self.anim_index += 1
        self.play_animation(anim_type)

    def play_animation(self, anim_type):
        if anim_type == "run":
            self.start_running()
            return

        self.is_animating = True
        self.anim_type = anim_type
        self.anim_frame = 0
        self.anim_base_x = self.x()
        self.anim_base_y = self.y()
        self.anim_base_w = self.width()
        self.anim_base_h = self.height()

        self.show_bubble(random.choice(DIALOGUES[anim_type]))

        durations = {"jump":14, "squash":16, "shake":18, "touch_head":20,
                     "feed":20, "drink":16, "off_work":24}
        self.anim_total = durations.get(anim_type, 14)
        self.anim_timer.start(30)

    def anim_step(self):
        import math
        f = self.anim_frame
        t = self.anim_type
        total = self.anim_total

        if t == "jump":
            half = total // 2
            p = f / half if f <= half else (f - half) / half
            offset_y = -50 * (p if f <= half else (1 - p))
            self.move(self.anim_base_x, int(self.anim_base_y + offset_y))

        elif t == "squash":
            half = total // 2
            if f <= half:
                p = f / half
                w = int(self.anim_base_w * (1 + 0.3 * p))
                h = int(self.anim_base_h * (1 - 0.3 * p))
            else:
                p = (f - half) / half
                overshoot = 0.12 * (1 - p*2) if p < 0.5 else -0.06 * (p-0.5)*2
                w = int(self.anim_base_w * (1 - 0.3*p + overshoot))
                h = int(self.anim_base_h * (1 + 0.3*p - overshoot))
            self.resize_pet(w, h, bottom_align=True)

        elif t == "shake":
            offset_x = 18 * math.sin(f * math.pi / 2)
            self.move(int(self.anim_base_x + offset_x), self.anim_base_y)

        elif t == "touch_head":
            offset_y = -10 * abs(math.sin(f * math.pi / 5))
            self.move(self.anim_base_x, int(self.anim_base_y + offset_y))

        elif t == "feed":
            if f % 4 < 2:
                h = int(self.anim_base_h * 0.96)
                self.resize_pet(self.anim_base_w, h, bottom_align=True)
                self.move(self.x(), int(self.anim_base_y + 6))
            else:
                self.resize_pet(self.anim_base_w, self.anim_base_h, bottom_align=True)
                self.move(self.x(), self.anim_base_y)

        elif t == "drink":
            half = total // 2
            p = f / half if f <= half else (f - half) / half
            offset_y = -12 * (p if f <= half else (1-p))
            h = int(self.anim_base_h * (1 + 0.04 * (p if f <= half else (1-p))))
            self.resize_pet(self.anim_base_w, h, bottom_align=True)

        elif t == "off_work":
            offset_x = 10 * math.sin(f * math.pi / 6)
            self.move(int(self.anim_base_x + offset_x), self.anim_base_y)

        self.anim_frame += 1
        if self.anim_frame >= total:
            self.anim_timer.stop()
            self.move(self.anim_base_x, self.anim_base_y)
            self.update_pet_size()
            self.is_animating = False

    def resize_pet(self, w, h, bottom_align=False):
        w, h = max(w, 10), max(h, 10)
        old_bottom = self.y() + self.height()
        pix = self.original_pixmap.scaled(w, h, Qt.IgnoreAspectRatio, Qt.SmoothTransformation)
        if self.is_flipped:
            pix = pix.transformed(QTransform().scale(-1, 1), Qt.SmoothTransformation)
        self.pet_label.setPixmap(pix)
        self.pet_label.setFixedSize(w, h)
        self.setFixedSize(w, h)
        if bottom_align:
            self.move(self.x(), old_bottom - h)

    # 来回奔跑
    def start_running(self):
        if self.is_running:
            return
        self.is_running = True
        self.run_frame = 0
        self.show_bubble(random.choice(DIALOGUES["run"]))
        self.run_direction = 1
        self.is_flipped = False
        self.update_pet_size()
        self.run_timer.start(30)
        QTimer.singleShot(5000, self.stop_running)

    def stop_running(self):
        if self.is_running:
            self.run_timer.stop()
            self.is_running = False
            self.is_flipped = False
            self.update_pet_size()

    def run_step(self):
        import math
        screen = QApplication.primaryScreen().geometry()
        new_x = self.x() + self.run_speed * self.run_direction

        if new_x + self.width() > screen.width() - 10:
            self.run_direction = -1
            self.is_flipped = True
            self.update_pet_size()
        elif new_x < 10:
            self.run_direction = 1
            self.is_flipped = False
            self.update_pet_size()

        self.move(new_x, self.y())
        self.run_frame += 1

    # 气泡
    def show_bubble(self, text):
        self.bubble.setText(text)
        self.bubble.adjustSize()
        x = (self.width() - self.bubble.width()) // 2
        y = -self.bubble.height() - 12
        self.bubble.move(x, y)
        self.bubble.show()
        self.bubble_timer.start(2500)


if __name__ == "__main__":
    app = QApplication(sys.argv)
    pet = PetWindow()
    pet.show()
    sys.exit(app.exec())
